<?php
 namespace QQWorld\Setup\Console\Command; use Symfony\Component\Console\Tester\CommandTester; class DependenciesShowFrameworkCommandTest extends \PHPUnit\Framework\TestCase { private $command; private $commandTester; public function setUp() { $modules = [ 'QQWorld_A' => __DIR__ . '/_files/root/app/code/QQWorld/A', 'QQWorld_B' => __DIR__ . '/_files/root/app/code/QQWorld/B' ]; $objectManagerProvider = $this->createMock(\QQWorld\Setup\Model\ObjectManagerProvider::class); $objectManager = $this->createMock(\QQWorld\Framework\App\ObjectManager::class); $objectManagerProvider->expects($this->once())->method('get')->willReturn($objectManager); $themePackageListMock = $this->createMock(\QQWorld\Framework\View\Design\Theme\ThemePackageList::class); $componentRegistrarMock = $this->createMock(\QQWorld\Framework\Component\ComponentRegistrar::class); $componentRegistrarMock->expects($this->any())->method('getPaths')->will($this->returnValue($modules)); $dirSearchMock = $this->createMock(\QQWorld\Framework\Component\DirSearch::class); $dirSearchMock->expects($this->once())->method('collectFiles')->willReturn( [ __DIR__ . '/_files/root/app/code/QQWorld/A/etc/module.xml', __DIR__ . '/_files/root/app/code/QQWorld/B/etc/module.xml' ] ); $objectManager->expects($this->any())->method('get')->will($this->returnValueMap([ [\QQWorld\Framework\View\Design\Theme\ThemePackageList::class, $themePackageListMock], [\QQWorld\Framework\Component\ComponentRegistrar::class, $componentRegistrarMock], [\QQWorld\Framework\Component\DirSearch::class, $dirSearchMock] ])); $this->command = new DependenciesShowFrameworkCommand($componentRegistrarMock, $objectManagerProvider); $this->commandTester = new CommandTester($this->command); } public function tearDown() { if (file_exists(__DIR__ . '/_files/output/framework.csv')) { unlink(__DIR__ . '/_files/output/framework.csv'); } } public function testExecute() { $this->commandTester->execute( ['--output' => __DIR__ . '/_files/output/framework.csv'] ); $this->assertEquals('Report successfully processed.' . PHP_EOL, $this->commandTester->getDisplay()); $fileContents = file_get_contents(__DIR__ . '/_files/output/framework.csv'); $this->assertContains( '"Dependencies of framework:","Total number"' . PHP_EOL . ',2' . PHP_EOL, $fileContents ); $this->assertContains('"Dependencies for each module:",' . PHP_EOL, $fileContents); $this->assertContains('"QQWorld\A",1' . PHP_EOL . '" -- QQWorld\Framework",2' . PHP_EOL, $fileContents); $this->assertContains('"QQWorld\B",1' . PHP_EOL . '" -- QQWorld\Framework",2' . PHP_EOL, $fileContents); } } 